INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0008-0001-0001-000000000001', '22222222-0001-0001-0001-000000000008', 'Translating Words to Math', 'Learn to turn everyday sentences into mathematical expressions', 1, 'tutorial', 15, 5, 820, 'al-Khwarizmi',
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0801-0001-0001-000000000001', '33333333-0008-0001-0001-000000000001', 'multiple_choice', 'easy', 'Which mathematical operation does the word "total" usually indicate?', NULL, '[{"id":"a","text":"Subtraction"},{"id":"b","text":"Division"},{"id":"c","text":"Addition"},{"id":"d","text":"Multiplication"}]'::jsonb, '"c"'::jsonb, '"Total" means adding things together. "How many in total?" = add them up.', 'If you find the total, you combine everything together', 5, 1),
('44444444-0801-0001-0001-000000000002', '33333333-0008-0001-0001-000000000001', 'multiple_choice', 'easy', 'The phrase "how many are left" usually means you should:', NULL, '[{"id":"a","text":"Add"},{"id":"b","text":"Subtract"},{"id":"c","text":"Multiply"},{"id":"d","text":"Divide"}]'::jsonb, '"b"'::jsonb, '"How many are left" means some were taken away — that''s subtraction.', 'If something is removed and you want what remains...', 5, 2),
('44444444-0801-0001-0001-000000000003', '33333333-0008-0001-0001-000000000001', 'multiple_choice', 'easy', 'Translate: "Sarah has 3 times as many books as Tom." If Tom has x books, how many does Sarah have?', NULL, '[{"id":"a","text":"x + 3"},{"id":"b","text":"x - 3"},{"id":"c","text":"3x"},{"id":"d","text":"x ÷ 3"}]'::jsonb, '"c"'::jsonb, '"3 times as many" means multiply by 3. Sarah has 3x books.', '"Times as many" = multiplication', 5, 3),
('44444444-0801-0001-0001-000000000004', '33333333-0008-0001-0001-000000000001', 'fill_in_blank', 'easy', 'Translate and solve: "A number plus 7 equals 15. What is the number?"', NULL, NULL, '"8"'::jsonb, 'x + 7 = 15, so x = 15 - 7 = 8.', 'What plus 7 gives you 15?', 5, 4),
('44444444-0801-0001-0001-000000000005', '33333333-0008-0001-0001-000000000001', 'multiple_choice', 'easy', 'Which word from al-Khwarizmi gave us the term "algebra"?', NULL, '[{"id":"a","text":"al-hisab (calculation)"},{"id":"b","text":"al-jabr (restoration)"},{"id":"c","text":"al-raqm (number)"},{"id":"d","text":"al-handasa (geometry)"}]'::jsonb, '"b"'::jsonb, 'The word "algebra" comes from "al-jabr" meaning restoration or completion — the process of moving terms to the other side of an equation.', 'It means moving things across the equals sign', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0008-0001-0001-000000000002', '22222222-0001-0001-0001-000000000008', 'Addition & Subtraction Word Problems', 'Solve real-world problems using addition and subtraction', 2, 'practice', 15, 5, NULL, NULL, NULL)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0802-0001-0001-000000000001', '33333333-0008-0001-0001-000000000002', 'fill_in_blank', 'easy', 'A shop had 145 apples. They sold 67. How many are left?', NULL, NULL, '"78"'::jsonb, '145 - 67 = 78 apples remaining.', 'Start with 145, take away 67', 5, 1),
('44444444-0802-0001-0001-000000000002', '33333333-0008-0001-0001-000000000002', 'fill_in_blank', 'easy', 'Tom has 23 marbles. His friend gives him 18 more. How many does Tom have now?', NULL, NULL, '"41"'::jsonb, '23 + 18 = 41 marbles.', 'He starts with some and gets more', 5, 2),
('44444444-0802-0001-0001-000000000003', '33333333-0008-0001-0001-000000000002', 'fill_in_blank', 'medium', 'A bus has 52 passengers. At the first stop, 18 get off and 7 get on. How many passengers are on the bus now?', NULL, NULL, '"41"'::jsonb, '52 - 18 + 7 = 41 passengers.', 'Some leave (subtract) and some join (add)', 10, 3),
('44444444-0802-0001-0001-000000000004', '33333333-0008-0001-0001-000000000002', 'multiple_choice', 'medium', 'Maria saved $125 in January and $98 in February. She spent $156 on a jacket. How much does she have left?', NULL, '[{"id":"a","text":"$67"},{"id":"b","text":"$57"},{"id":"c","text":"$77"},{"id":"d","text":"$47"}]'::jsonb, '"a"'::jsonb, '$125 + $98 = $223 total saved. $223 - $156 = $67 remaining.', 'Add her savings first, then subtract the purchase', 10, 4),
('44444444-0802-0001-0001-000000000005', '33333333-0008-0001-0001-000000000002', 'fill_in_blank', 'medium', 'The temperature was -3°C in the morning and rose by 11 degrees by afternoon. What was the afternoon temperature? (Include sign if negative)', NULL, NULL, '"8"'::jsonb, '-3 + 11 = 8°C.', 'Start at -3 and go up 11', 10, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0008-0001-0001-000000000003', '22222222-0001-0001-0001-000000000008', 'Multiplication & Division Word Problems', 'Solve real-world problems using multiplication and division', 3, 'practice', 15, 5, NULL, NULL, NULL)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0803-0001-0001-000000000001', '33333333-0008-0001-0001-000000000003', 'fill_in_blank', 'easy', 'Each box holds 12 eggs. How many eggs are in 5 boxes?', NULL, NULL, '"60"'::jsonb, '12 × 5 = 60 eggs.', 'Multiply the number of boxes by eggs per box', 5, 1),
('44444444-0803-0001-0001-000000000002', '33333333-0008-0001-0001-000000000003', 'fill_in_blank', 'easy', '72 students need to be divided into teams of 8. How many teams will there be?', NULL, NULL, '"9"'::jsonb, '72 ÷ 8 = 9 teams.', 'Divide the total by the team size', 5, 2),
('44444444-0803-0001-0001-000000000003', '33333333-0008-0001-0001-000000000003', 'fill_in_blank', 'medium', 'A car travels at 65 km/h for 3 hours. How far does it go? (Just the number)', NULL, NULL, '"195"'::jsonb, 'Distance = speed × time = 65 × 3 = 195 km.', 'Distance = speed × time', 10, 3),
('44444444-0803-0001-0001-000000000004', '33333333-0008-0001-0001-000000000003', 'multiple_choice', 'medium', 'A pack of 6 juice boxes costs $4.50. How much is each juice box?', NULL, '[{"id":"a","text":"$0.65"},{"id":"b","text":"$0.75"},{"id":"c","text":"$0.80"},{"id":"d","text":"$0.50"}]'::jsonb, '"b"'::jsonb, '$4.50 ÷ 6 = $0.75 each.', 'Divide the total cost by the number of items', 10, 4),
('44444444-0803-0001-0001-000000000005', '33333333-0008-0001-0001-000000000003', 'fill_in_blank', 'medium', 'A garden is 15 meters long and 8 meters wide. What is its area in square meters?', NULL, NULL, '"120"'::jsonb, 'Area = length × width = 15 × 8 = 120 m².', 'Area of a rectangle = length × width', 10, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0008-0001-0001-000000000004', '22222222-0001-0001-0001-000000000008', 'Mixed Word Problems', 'Tackle word problems that require multiple operations', 4, 'practice', 15, 7, NULL, NULL, NULL)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0804-0001-0001-000000000001', '33333333-0008-0001-0001-000000000004', 'fill_in_blank', 'medium', 'You buy 3 shirts at $15 each and 2 pairs of socks at $4 each. What is the total cost?', NULL, NULL, '"53"'::jsonb, '3 × $15 + 2 × $4 = $45 + $8 = $53.', 'Calculate each item type separately, then add', 10, 1),
('44444444-0804-0001-0001-000000000002', '33333333-0008-0001-0001-000000000004', 'multiple_choice', 'medium', 'A school has 240 students. 3/4 of them play sport. How many play sport?', NULL, '[{"id":"a","text":"160"},{"id":"b","text":"180"},{"id":"c","text":"200"},{"id":"d","text":"120"}]'::jsonb, '"b"'::jsonb, '3/4 of 240 = 240 × 3/4 = 720/4 = 180 students.', 'Multiply 240 by 3, then divide by 4', 10, 2),
('44444444-0804-0001-0001-000000000003', '33333333-0008-0001-0001-000000000004', 'fill_in_blank', 'medium', 'A movie ticket costs $12. A group of 5 friends buys tickets and splits a $20 popcorn combo equally. How much does each person pay in total?', NULL, NULL, '"16"'::jsonb, 'Ticket: $12. Popcorn share: $20 ÷ 5 = $4. Total per person: $12 + $4 = $16.', 'Calculate ticket cost + share of popcorn', 10, 3),
('44444444-0804-0001-0001-000000000004', '33333333-0008-0001-0001-000000000004', 'fill_in_blank', 'hard', 'A tank holds 500 liters. It loses 15 liters per day through a leak but gets refilled by 40 liters every 3 days. After 6 days, how many liters are left?', NULL, NULL, '"490"'::jsonb, 'Loss over 6 days: 15 × 6 = 90 liters. Refills: 40 × 2 = 80 liters (refilled on day 3 and day 6). Net: 500 - 90 + 80 = 490 liters.', 'Calculate total loss and total refill separately', 15, 4),
('44444444-0804-0001-0001-000000000005', '33333333-0008-0001-0001-000000000004', 'multiple_choice', 'hard', 'A store has a "buy 2 get 1 free" offer on $9 books. How much do 5 books cost?', NULL, '[{"id":"a","text":"$36"},{"id":"b","text":"$27"},{"id":"c","text":"$45"},{"id":"d","text":"$30"}]'::jsonb, '"a"'::jsonb, 'With "buy 2 get 1 free": first 3 books cost 2 × $9 = $18 (third is free). Next 2 books cost 2 × $9 = $18. Total: $18 + $18 = $36.', 'In groups of 3, you only pay for 2', 15, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0008-0001-0001-000000000005', '22222222-0001-0001-0001-000000000008', 'Word Problems Boss', 'Master real-world word problems!', 5, 'boss_round', 30, 5, NULL, NULL, NULL)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0805-0001-0001-000000000001', '33333333-0008-0001-0001-000000000005', 'fill_in_blank', 'medium', 'A pizza has 8 slices. You eat 3/8 and your friend eats 1/4. How many slices are left? (Just the number)', NULL, NULL, '"3"'::jsonb, 'You eat 3/8 = 3 slices. Friend eats 1/4 = 2/8 = 2 slices. Left: 8 - 3 - 2 = 3 slices.', 'Convert 1/4 to eighths first', 10, 1),
('44444444-0805-0001-0001-000000000002', '33333333-0008-0001-0001-000000000005', 'fill_in_blank', 'hard', 'A train leaves at 9:15 AM traveling at 80 km/h. Another train leaves the same station at 10:00 AM traveling at 100 km/h in the same direction. At what time does the second train catch up? (Format: HH:MM AM)', NULL, NULL, '"1:00 PM"'::jsonb, 'Train 1 has a 45-min (0.75 hr) head start = 60 km lead. Train 2 gains 20 km/h. Time to catch up: 60/20 = 3 hours after 10:00 AM = 1:00 PM.', 'How much head start does train 1 have? How fast does train 2 close the gap?', 15, 2),
('44444444-0805-0001-0001-000000000003', '33333333-0008-0001-0001-000000000005', 'multiple_choice', 'hard', 'A $300 laptop is on sale for 15% off. Sales tax is 10% (applied after the discount). What is the final price?', NULL, '[{"id":"a","text":"$280.50"},{"id":"b","text":"$283.50"},{"id":"c","text":"$255.00"},{"id":"d","text":"$267.50"}]'::jsonb, '"a"'::jsonb, 'Discount: $300 × 0.85 = $255. Tax: $255 × 1.10 = $280.50.', 'Apply discount first, then add tax to the discounted price', 15, 3),
('44444444-0805-0001-0001-000000000004', '33333333-0008-0001-0001-000000000005', 'fill_in_blank', 'hard', 'You mix 2 liters of juice concentrate with water in a ratio of 1:4 (concentrate to water). How many liters of juice do you make in total?', NULL, NULL, '"10"'::jsonb, 'Ratio 1:4 means for every 1 part concentrate, add 4 parts water. 2 liters concentrate needs 2 × 4 = 8 liters water. Total: 2 + 8 = 10 liters.', 'If 1 part concentrate = 2 liters, then 4 parts water = ?', 15, 4),
('44444444-0805-0001-0001-000000000005', '33333333-0008-0001-0001-000000000005', 'fill_in_blank', 'hard', 'A rectangular pool is 25m long and 10m wide. You want to build a 2m-wide path around it. What is the total area including the path? (in m²)', NULL, NULL, '"406"'::jsonb, 'Pool + path: length = 25 + 2 + 2 = 29m, width = 10 + 2 + 2 = 14m. Total area = 29 × 14 = 406 m².', 'The path adds 2m to EACH side', 15, 5)
